{
  "concepts": [
    {
      "conditions": [],
      "definition": "A declared frame set's operational full coverage is relative to Coverage(W, G, B, E, S, T) and the eight stated criteria. It does not assert that no undiscovered evaluation exists.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1032,
          "quote": "The exact predicate is “the declared frame set has operational full coverage\nfor `Coverage(W, G, B, E, S, T)` under these eight criteria”.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FWorkspace%20Coverage%2FOperational%20Full%20Coverage",
          "start_line": 1031
        }
      ],
      "key": "operational_full_coverage",
      "label": "Operational full coverage"
    },
    {
      "conditions": [],
      "definition": "Separately activated frame coverage for evaluations with high-consequence failure, weak observability, strong confirmation bias, or a history of local proof masking.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1010,
          "quote": "Human authority may require independently activated frame coverage for\nevaluations whose failure has high consequence, weak observability, strong\nconfirmation bias, or a history of local proof masking.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FWorkspace%20Coverage%2FHigh-Risk%20Separately%20Activated%20Coverage",
          "start_line": 1008
        }
      ],
      "key": "high_risk_coverage",
      "label": "High-risk separately activated coverage"
    },
    {
      "conditions": [],
      "definition": "The Reference Frame Method describes finite, evaluation-bound, basis-bound, authority-safe frames usable within actor capability envelopes, with explicit residuals and materially required cross-frame relations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1518,
          "quote": "2. every active frame is finite, evaluation-bound, basis-bound, authority-safe,\n   and usable inside its actor capability envelope;",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FClosure",
          "start_line": 1517
        }
      ],
      "key": "reference_frame_method",
      "label": "Reference Frame Method"
    },
    {
      "conditions": [],
      "definition": "An ordered investigation of activation, exact subject and basis, actor capability, evidence, missing variables or invariants, missing conjunction or translation, evaluation-family adequacy, and finally need for another frame.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1106,
          "quote": "1. Was the correct declared frame activated?\n2. Was the subject and basis exact?\n3. Was the actor inside the capability envelope?\n4. Was admissible evidence available?\n5. Is a material variable or invariant missing from the frame?\n6. Is a required conjunction or translation missing?\n7. Is the evaluation family itself wrong or incomplete?\n8. Is another frame required?",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FDiscovery%20And%20Revision%2FDiagnostic%20Order",
          "start_line": 1099
        }
      ],
      "key": "frame_diagnosis",
      "label": "Frame diagnosis"
    },
    {
      "conditions": [],
      "definition": "A change to frame activation, evidence acquisition, capability, material relations, partitioning, overlap, conjunction, translation, retirement, or project evaluation inventory.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1122,
          "quote": "- clarify activation or evidence acquisition;\n- change the capability envelope;\n- add or remove a material relation;\n- split an overloaded frame;\n- merge duplicative frames where capability and authority remain sound;\n- add intentional overlap;\n- add or revise a conjunction or translation;\n- retire a frame whose evaluation family is no longer material; or\n- revise the project evaluation inventory.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FDiscovery%20And%20Revision%2FRevision%20Actions",
          "start_line": 1114
        }
      ],
      "key": "frame_revision",
      "label": "Frame revision"
    },
    {
      "conditions": [],
      "definition": "An RF-017 projection of a bound frame tuple, identity and revision, actual subject, admissible inputs/tools, and stop/reconfiguration conditions, supplied as one activated frame or declared active configuration.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1139,
          "quote": "The packet is the RF-017 projection of the bound frame tuple, its identity and\nrevision, actual subject, admissible inputs/tools, and stop/reconfiguration\nconditions. [Select And Activate](#select-and-activate) decides sufficiency;\nthe binding below exposes these coordinates in a carrier-neutral form.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FAgentic%20Use",
          "start_line": 1136
        }
      ],
      "key": "frame_packet",
      "label": "Agent frame packet"
    },
    {
      "conditions": [],
      "definition": "A carrier-neutral template sufficient to bind one declared frame for one evaluation. It records stable activation identity; declaration identity/revision and exact evaluation/core predicate or refinement; exact subject; workspace, authority, dependency, configuration and time basis; material relations/invariants, exact source/semantic references, exclusions/prohibited assumptions; actor/capability; semantic/evaluation, material operation/subject/territory, decision/acceptance/publication authority; evidence/acquisition; used dependency, overlap, input, conjunction or translation relations; result consumer/return relation; invalidation and stop/residual/re-entry/reconfiguration conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1154,
          "quote": "The following carrier-neutral content is sufficient to bind one declared frame\nfor one evaluation. It may be written in Markdown, structured data, a prompt,\nor another Product-selected carrier without changing the relation.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FAgentic%20Use%2FMinimal%20Frame%20Activation%20Binding",
          "start_line": 1152
        },
        {
          "end_line": 1185,
          "quote": "## Stop And Change\n- invalidation conditions:\n- stop, residual, re-entry, and reconfiguration conditions:",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FAgentic%20Use%2FMinimal%20Frame%20Activation%20Binding",
          "start_line": 1183
        }
      ],
      "key": "frame_activation_binding",
      "label": "Minimal frame activation binding"
    },
    {
      "conditions": ["Illustrative, non-normative example only."],
      "definition": "The product-chain-drift binding uses activation urn:example:activation:product-chain-drift:1 and frame urn:example:frame:product-chain-drift:1 to ask whether candidate urn:example:candidate:change:7 preserves the selected Product definition and every affected contract. It binds checkpoint urn:example:checkpoint:source:42; source project urn:example:source-project:authoring-product; configuration urn:example:configuration:product-change-review:2; time urn:example:time-basis:2026-08-31T00:00:00Z; and the cited example product-definition, work-authority, development-substrate Product and local Install, dependency Product and authoring-to-dependency contract. Its result domain is satisfied, falsified, indeterminate, out_of_frame, invalid_basis.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1208,
          "quote": "- evaluation and exact predicate:\n  Does candidate urn:example:candidate:change:7 preserve the selected Product\n  definition and every affected contract in the declared Product chain?\n- result algebra:\n  satisfied | falsified | indeterminate | out_of_frame | invalid_basis",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FAgentic%20Use%2FWorked%20Binding%3A%20Product-Chain%20Drift%20Evaluation",
          "start_line": 1204
        },
        {
          "end_line": 1195,
          "quote": "This non-normative example demonstrates a complete prose binding. It defines no\nuniversal Product profile and selects no implementation or representation.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FAgentic%20Use%2FWorked%20Binding%3A%20Product-Chain%20Drift%20Evaluation",
          "start_line": 1194
        }
      ],
      "key": "product_chain_drift_example",
      "label": "Worked product-chain drift binding"
    },
    {
      "conditions": [],
      "definition": "Proportional qualification of a candidate frame's claims, bound to the exact frame revision, actor envelope, evaluation family, basis class, and evidence conditions actually evaluated.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1328,
          "quote": "Qualification binds the exact frame revision, actor envelope, evaluation\nfamily, basis class, and evidence conditions evaluated. It does not generalize\nto an unevaluated population by naming the frame generically.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FFrame%20Qualification",
          "start_line": 1326
        }
      ],
      "key": "frame_qualification",
      "label": "Frame qualification"
    },
    {
      "conditions": [],
      "definition": "Qualification of the method's complete claimed function and failure-relation population under externally supplied constructor, freeze, assessor, acceptance and release protocols.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1345,
          "quote": "Qualification of this method uses the constructor, freeze, assessor,\nacceptance, and release protocols supplied by its external governing\nauthority; it does not define those protocols. A fresh competent constructor\noperates inside a declared capability, context, and configuration envelope\nusing this method and declared trial subjects. An independently authorized\nevaluator then compares the exact stabilized results with this method's\ncomplete mandatory relation population.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FFrame%20Qualification%2FMethod%20Self-Qualification",
          "start_line": 1339
        }
      ],
      "key": "method_self_qualification",
      "label": "Method self-qualification"
    },
    {
      "conditions": [],
      "definition": "A frame declaration template records stable local identity; evaluation questions, predicates and applicable core-result refinement; workspace boundary and exact identity/version/time/topology; entities, variables, relations, states and interactions; coordinates/equality; applicable governing invariants; frame-set, semantic, evaluation, material operation and decision authorities; evidence/provenance/exclusions; competence, context, access, tools, evaluation/assurance independence and configuration; boundary/prohibited assumptions/out-of-frame conditions; only optional input/output/overlap/conjunction/translation relations actually used; invalidation/recharting; representative qualification cases, counterexamples and known residuals.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1448,
          "quote": "## Optional Frame Relations\n<inputs, outputs, overlaps, conjunctions, or translations actually used>\n\n## Invalidation And Recharting\n<changes that stale this frame or its results>\n\n## Qualification\n<representative cases, counterexamples, and known residuals>",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FMinimal%20Frame%20Declaration",
          "start_line": 1441
        }
      ],
      "key": "frame_declaration_template",
      "label": "Minimal frame declaration"
    },
    {
      "conditions": [],
      "definition": "A frame-set declaration template records stable local identity; workspace/outcome/basis/time; human declaration and acceptance authority; known material evaluations and provenance; selected frame identities/revisions/capability envelopes; mapping to capable frames; intentional separately activated checks, assurance-independence or alternative capability fit; only cross-frame conjunction/translation relations required by evaluations; uncovered, unknown, conditional or excluded evaluations; and history/topology/capability/evidence/outcome revision triggers.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1483,
          "quote": "## Intentional Overlap\n<separately activated checks, assurance-independence conditions, or alternative capability fit>\n\n## Conjunction And Translation\n<only the cross-frame relations required by evaluations>\n\n## Residual Uncertainty\n<uncovered, unknown, conditional, or excluded evaluations>\n\n## Revision Triggers\n<history, topology, capability, evidence, or outcome changes>",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FMinimal%20Frame-Set%20Declaration",
          "start_line": 1473
        }
      ],
      "key": "frame_set_declaration_template",
      "label": "Minimal frame-set declaration"
    },
    {
      "conditions": [],
      "definition": "A result template records frame identity/revision, activation identity, evaluation, exact predicate/domain refinement, subject/basis, actor/capability, semantic/evaluation/material operation/decision authority, admissible evidence, core verdict and original domain outcome, performance and known effect state, inference relation, residual uncertainty, invalidation conditions and consuming decision or conjunction.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1506,
          "quote": "- core verdict and original domain outcome:\n- performance and known effect state:\n- inference relation:\n- residual uncertainty:\n- invalidation conditions:\n- consuming decision or conjunction:",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FMinimal%20Evaluation%20Result",
          "start_line": 1501
        }
      ],
      "key": "frame_result_template",
      "label": "Minimal evaluation result"
    },
    {
      "conditions": [],
      "definition": "RELEASE_METHOD.md owns release-specific identity, qualification, publication and selection contracts and urn:stdo:bounded-context:release-publication under the selected complete STDO basis. Its identities and transitions qualify, publish and select released cuts; consumer Product meaning and adoption decisions remain with the consumer's governing authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 10,
          "quote": "This member owns release-specific identity, qualification, publication and\nselection contracts.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method",
          "start_line": 3
        },
        {
          "end_line": 29,
          "quote": "`RELEASE_METHOD.md` owns the release-publication bounded context\n`urn:stdo:bounded-context:release-publication` under the selected complete STDO\nbasis. It owns the identities and transitions used to qualify, publish, and\nselect released cuts, including the selector/adoption protocol below. It does\nnot own the consumer's Product meaning or its decision to adopt a cut; those\nremain with the consumer's governing authority under Spec's Product binding.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease-Publication%20Context",
          "start_line": 24
        }
      ],
      "key": "release_method",
      "label": "Release Method and release-publication context"
    },
    {
      "conditions": [],
      "definition": "A stable repository-local key assigned by Product release authority to one independently released source project.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 97,
          "quote": "- **Project Release Namespace** — a stable repository-local key assigned by the\n  Product release authority to one independently released source project;",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease%20Identities",
          "start_line": 96
        }
      ],
      "key": "project_release_namespace",
      "label": "Project Release Namespace"
    },
    {
      "conditions": [],
      "definition": "The exact repository-relative source-project root and Git tree object selected for one cut; the root is a locator inside the exact peeled commit rather than Product identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 99,
          "quote": "- **Project Subtree** — the exact repository-relative source-project root and\n  Git tree object selected for one cut;",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease%20Identities",
          "start_line": 98
        },
        {
          "end_line": 161,
          "quote": "The Project Subtree root is a locator inside the exact peeled commit, not\nProduct identity.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FProject-Subtree%20Release%20Identity",
          "start_line": 160
        }
      ],
      "key": "project_subtree",
      "label": "Project Subtree"
    },
    {
      "conditions": [],
      "definition": "Mutable source-project state constructing a possible successor; distinct from the mutable project-qualified RC Branch carrying its current candidate window.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 103,
          "quote": "- **Candidate Source** — mutable source-project state constructing a possible\n  successor;\n- **RC Branch** — a mutable project-qualified carrier for the current candidate\n  window;",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease%20Identities",
          "start_line": 100
        }
      ],
      "key": "candidate_source",
      "label": "Candidate Source and RC Branch"
    },
    {
      "conditions": [],
      "definition": "An annotated project-qualified Git tag plus its exact Product release subject, naming one published candidate and, once accepted, one released Product.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 106,
          "quote": "- **Immutable RC Cut** — an annotated project-qualified Git tag plus its exact\n  Product release subject, naming one published candidate and, once accepted,\n  one released Product;",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease%20Identities",
          "start_line": 104
        }
      ],
      "key": "immutable_rc_cut",
      "label": "Immutable RC Cut"
    },
    {
      "conditions": [],
      "definition": "A mutable project-qualified tag alias naming the greatest positive published RC ordinal for one project and version line. It supplies discovery, not immutable constitutional, dependency, evidence or replay identity. The optional Release Branch is a mutable convenience carrier aligned to the same latest-published commit.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 111,
          "quote": "- **Version-Line Selector** — the mutable project-qualified tag alias naming\n  the highest-ordinal published immutable RC cut for that project and version\n  line; and\n- **Release Branch** — an optional mutable project-qualified convenience\n  carrier aligned to the same latest-published commit as the selector.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease%20Identities",
          "start_line": 107
        },
        {
          "end_line": 77,
          "quote": "It denotes a mutable **Version-Line Selector**. The selector points to the\nlatest published immutable RC cut on that line, where latest means the greatest\npositive RC ordinal published for that project and version line. It is\nconvenient discovery, not immutable identity and not sufficient as an exact\nconstitutional, dependency, evidence, or replay basis.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FPosition",
          "start_line": 73
        }
      ],
      "key": "version_line_selector",
      "label": "Version-Line Selector and optional Release Branch"
    },
    {
      "conditions": [],
      "definition": "Qualification bound to the exact release identity, release-scoped claim bytes, governing Product/release basis, each property and observation boundary, evidence subjects, assessment results, owner decisions, unresolved gaps and complete successor relation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 300,
          "quote": "- the exact release-scoped claim bytes;\n- the governing Product and release basis;\n- each claimed property and its observation boundary;\n- evidence subjects, assessment results, owner decisions and unresolved gaps; and\n- the complete successor relation to the declared predecessor.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FExact-Cut%20Qualification",
          "start_line": 296
        }
      ],
      "key": "exact_cut_qualification",
      "label": "Exact-cut qualification"
    },
    {
      "conditions": [],
      "definition": "A separate explicit Product-Definition transition that resolves, presents, installs, verifies and pins a selected immutable RC under consumer authority. Discovering publication or moving a selector does not perform adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 380,
          "quote": "Moving\nthe Git version-line selector does not update any consumer. Adoption is a\nseparate explicit Product-Definition transition that resolves, presents,\ninstalls, verifies, and pins the selected immutable RC.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FSelector%20And%20Consumer%20Adoption",
          "start_line": 377
        }
      ],
      "key": "consumer_adoption",
      "label": "Consumer adoption"
    },
    {
      "conditions": [],
      "definition": "Optional RC-carried release notes, release/installed-distribution manifests, dependency declarations, package/installed-carrier metadata, qualification receipts and branch/tag identity declarations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 443,
          "quote": "An immutable RC cut may carry release-scoped surfaces such as:\n\n- release notes;\n- release and installed-distribution manifests;\n- dependency declarations;\n- package or installed-carrier metadata;\n- qualification receipts; and\n- branch and tag identity declarations.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FRelease-Scoped%20Assets",
          "start_line": 436
        }
      ],
      "key": "release_scoped_assets",
      "label": "Release-scoped assets"
    },
    {
      "conditions": ["Explicit declaration by Product authority when a source corpus and its required distributed or derived assets must remain usable as one versioned set."],
      "definition": "A cross-Product Release-Matched Asset Cohort names every required Product and asset, exact source dependency, owning authorities, qualification boundary and publication transaction. Co-location, equal versions and a common actor cannot infer it.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 470,
          "quote": "A Product authority may declare an explicit cross-Product **Release-Matched\nAsset Cohort** when one source corpus and its required distributed or derived\nassets must remain usable as one versioned set. The declaring relation names\nevery required Product and asset, the exact source dependency, its owning\nauthorities, the qualification boundary, and the publication transaction. Path\nco-location, equal version text, or a common actor cannot infer the relation.",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FCoordinated%20Release-Matched%20Asset%20Cohorts",
          "start_line": 465
        }
      ],
      "key": "release_matched_cohort",
      "label": "Release-Matched Asset Cohort"
    },
    {
      "conditions": ["A coordinated STDO cohort uses an installed-manifest identity containing the annotated STDO tag object."],
      "definition": "A bounded two-commit construction avoids embedding a tag's identity and derived child bytes in the same self-referential commit; one qualified atomic transaction subsequently publishes the complete ref set.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 513,
          "quote": "Exact installed-manifest identity includes the annotated STDO tag object, so a\nsame-commit carrier containing both that identity and derived child bytes would\nbe self-referential. A coordinated STDO cohort therefore uses this bounded\ntwo-commit construction:",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FCoordinated%20Release-Matched%20Asset%20Cohorts%2FTwo-Commit%20Construction%20And%20One%20Publication%20Transaction",
          "start_line": 510
        }
      ],
      "key": "cohort_two_commit_construction",
      "label": "Two-commit cohort construction"
    },
    {
      "conditions": [],
      "definition": "STDO-UP-015 assigns one semantic disposition to every predecessor claim capable of affecting a successor: conserved retains meaning; superseded uses an accepted replacement relation; intentionally removed requires current Product authority's removal; not applicable requires a bounded no-effect reason. These row dispositions are distinct from semantic and authorized-decision verdicts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 663,
          "quote": "A successor identifies the exact predecessor immutable RC whose semantic claims\nit evolves. That origin remains immutable for the candidate. Every predecessor\nclaim capable of affecting the successor receives one semantic disposition:\n\n- **conserved** — the successor retains the claim;\n- **superseded** — an accepted successor relation replaces it;\n- **intentionally removed** — current Product authority removes it; or\n- **not applicable** — it has no successor effect, with a bounded reason.\n\nThese are row dispositions, not interchangeable verdicts on retention. Bind\neach semantic assessment to the predicate for its exact predecessor claim and\nsuccessor relation:",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/RELEASE_METHOD.md#Release%20Method%2FSuccessor%20Baseline%20Conservation%20%28%60STDO-UP-015%60%29",
          "start_line": 652
        }
      ],
      "key": "successor_baseline_conservation",
      "label": "Successor baseline conservation"
    },
