      "exceptions": [],
      "grounding": [
        {
          "end_line": 468,
          "quote": "A **Constitutional Set** is the complete set of governing documents selected\nfor a product, not five prescribed files. Collectively, the selected set must\nmake the following recoverable for the governed scope:",
          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FConstitutional-Set%20Sufficiency",
          "start_line": 466
