          "section_id": "repo://stdo-v3-generation-rc9/codex/5592168e26759f37e730aed12c030a6061709ec4/source/standards/REFERENCE_FRAME_METHOD.md#Reference%20Frame%20Method%2FWorkspace%20Coverage%2FOperational%20Full%20Coverage",
